<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WeTalk Dashboard</title><style>
:root{--b:#0757df;--r:#ef2028;--n:#091735;--m:#72809a;--l:#e1e8f2;--s:#f4f7fc;--g:#12a45f}*{box-sizing:border-box}body{margin:0;height:100vh;font-family:Inter,Segoe UI,Arial,sans-serif;color:var(--n);background:#fff}button,input{font:inherit}button{cursor:pointer}.top{height:88px;border-bottom:1px solid var(--l);display:flex;align-items:center;padding:0 30px;gap:25px}.brand{display:flex;align-items:center;gap:8px;text-decoration:none;margin-right:auto}.mark{width:61px;height:58px;background:url('images/wetalk-logo-sheet.png') center 7%/175px auto no-repeat}.word{font-size:27px;font-weight:900;color:var(--b)}.word span{color:var(--r)}.search{width:min(325px,30vw);position:relative}.search input{width:100%;border:1px solid #dbe4f0;background:#f8faff;border-radius:12px;padding:12px 48px 12px 38px;outline:0}.search:before{content:'⌕';position:absolute;left:13px;top:9px;font-size:20px;color:#687791}.search kbd{position:absolute;right:9px;top:9px;border:0;background:#edf2f8;border-radius:6px;padding:4px 7px;color:#40506b}.bell{position:relative;border:0;background:transparent;font-size:21px}.bell i{position:absolute;right:-5px;top:-8px;background:var(--r);color:#fff;border-radius:50%;font-style:normal;font-size:9px;width:20px;height:20px;display:grid;place-items:center}.user{display:flex;align-items:center;gap:9px}.avatar{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(145deg,var(--b),#6c45dc);color:#fff;font-size:11px;font-weight:900}.user b{font-size:12px;display:block}.user small{font-size:10px;color:var(--m)}.shell{height:calc(100vh - 88px);display:grid;grid-template-columns:285px 290px minmax(430px,1fr) 275px}.global,.channels,.right{border-right:1px solid var(--l);overflow:auto;background:#fff}.global{display:flex;flex-direction:column;padding:25px 14px 0}.create{border:0;border-radius:10px;padding:14px;background:linear-gradient(135deg,var(--b),#1e74ed);color:#fff;font-weight:800;box-shadow:0 9px 20px #0757df20}.label{font-size:10px;font-weight:900;color:#8190a9;letter-spacing:.1em;margin:25px 10px 9px;text-transform:uppercase}.nav-btn,.item{width:100%;border:0;background:transparent;border-radius:10px;padding:11px 12px;display:flex;align-items:center;gap:12px;text-align:left;color:#1f2d48;margin:2px 0;text-decoration:none}.nav-btn:hover,.item:hover,.nav-btn.active,.item.active{background:#eaf1ff;color:var(--b)}.nav-btn.active,.item.active{font-weight:800}.ico{width:22px;text-align:center;font-size:17px}.count{margin-left:auto;width:22px;height:22px;border-radius:50%;background:var(--r);color:#fff;display:grid;place-items:center;font-size:9px}.community-dot{width:32px;height:32px;border-radius:10px;display:grid;place-items:center;color:#fff;background:linear-gradient(145deg,var(--b),#397ff0);font-size:10px;font-weight:900}.green{background:linear-gradient(145deg,#079357,#19bd6f)}.purple{background:linear-gradient(145deg,#7547e5,#a178f3)}.orange{background:linear-gradient(145deg,#ed8b13,#ffb33b)}.me{margin-top:auto;border-top:1px solid var(--l);padding:14px;display:flex;gap:10px;align-items:center}.me small{display:block;color:var(--g)}.channels{background:linear-gradient(180deg,#fff,#fbfdff)}.workspace{height:78px;padding:16px 20px;border-bottom:1px solid var(--l);display:flex;align-items:center;gap:12px}.workspace .community-dot{width:42px;height:42px;border-radius:50%;font-size:13px}.workspace b{font-size:13px}.channel-list{padding:12px 13px}.row-label{display:flex;align-items:center;margin:13px 9px 8px;color:#52617b;font-size:10px;font-weight:900}.row-label button{margin-left:auto;border:0;background:transparent;font-size:18px}.channel-list .item{padding:10px 12px}.voice-sep{border-top:1px solid var(--l);margin:18px -13px 0;padding:15px 13px 0}.chat{min-width:0;display:flex;flex-direction:column}.chat-head{height:78px;border-bottom:1px solid var(--l);display:flex;align-items:center;padding:12px 22px;gap:14px}.chat-head h1{font-size:18px;margin:0}.chat-head p{font-size:10px;color:var(--m);margin:4px 0 0}.chat-tools{margin-left:auto;display:flex;gap:7px}.chat-tools button{border:0;background:transparent;width:35px;height:35px;border-radius:9px;font-size:18px}.chat-tools button:hover{background:#eff4fb;color:var(--b)}.messages{flex:1;overflow:auto;padding:27px 24px;background:radial-gradient(circle at 100% 0,#edf3ff80,transparent 24%),#fff}.message{display:grid;grid-template-columns:42px 1fr;gap:11px;margin-bottom:22px;max-width:700px;animation:up .35s ease both}@keyframes up{from{opacity:0;transform:translateY(9px)}}.meta{display:flex;align-items:baseline;gap:8px}.meta b{font-size:13px;color:var(--b)}.meta time{font-size:10px;color:#91a0b5}.text{font-size:13px;line-height:1.55;margin-top:6px}.reactions{display:flex;gap:6px;margin-top:7px}.react{border:0;background:#f2f5fa;border-radius:8px;padding:5px 9px;font-size:10px}.announce{display:inline-block;margin-top:6px;background:linear-gradient(135deg,#e9f1ff,#f5f8ff);border-radius:5px 13px 13px 13px;padding:11px 14px;font-size:12px}.announce b{display:block;margin-bottom:5px}.new{display:flex;align-items:center;gap:12px;margin:25px 0}.new:before,.new:after{content:'';height:1px;background:#d9e3f1;flex:1}.new span{font-size:10px;border:1px solid #ccdcf4;color:var(--b);padding:6px 10px;border-radius:20px}.composer-wrap{padding:13px 22px 20px;border-top:1px solid var(--l)}.composer{display:grid;grid-template-columns:40px 1fr 40px 50px;gap:7px}.composer input{border:1px solid #cfdbe9;border-radius:11px;padding:12px;outline:0}.composer button{border:1px solid #d5e0ed;background:#fff;border-radius:10px;color:#53617a}.composer .send{border:0;background:linear-gradient(135deg,var(--b),#267bed);color:#fff;font-size:18px}.right{border-right:0;border-left:1px solid var(--l);padding:12px;background:#fbfdff}.card{border:1px solid var(--l);background:#fff;border-radius:14px;padding:16px;margin-bottom:12px}.card h2{font-size:12px;margin:0 0 15px}.member{display:grid;grid-template-columns:34px 1fr auto;gap:8px;align-items:center;padding:8px 0}.member .avatar{width:34px;height:34px}.member b{font-size:10px;display:block}.member small{font-size:9px;color:var(--g)}.role{font-size:8px;background:#e9f0ff;color:var(--b);padding:4px 6px;border-radius:6px}.more{color:var(--b);font-size:10px;font-weight:800}.stat{display:flex;justify-content:space-between;color:#75829a;font-size:10px;padding:10px 0}.settings{width:100%;margin-top:12px;border:0;border-radius:9px;padding:11px;background:#edf3ff;color:var(--b);font-weight:800;font-size:10px}.mobile{display:none}.overlay{display:none;position:fixed;inset:0;background:#06142d88;z-index:20}.overlay.open{display:block}@media(max-width:1220px){.shell{grid-template-columns:245px 250px 1fr}.right{display:none}}@media(max-width:900px){.shell{grid-template-columns:230px 1fr}.channels{display:none}.search{display:none}}@media(max-width:650px){.top{height:72px;padding:0 14px}.mark{width:48px;height:47px;background-size:145px}.word{font-size:22px}.user span:last-child{display:none}.shell{height:calc(100vh - 72px);grid-template-columns:1fr}.global{position:fixed;left:-285px;top:72px;bottom:0;width:275px;z-index:25;transition:.25s}.global.open{left:0}.mobile{display:block;border:0;background:#eef3fa;border-radius:9px;width:38px;height:38px}.chat-head{height:69px;padding:10px 12px}.messages{padding:20px 14px}.chat-tools button:nth-child(-n+2){display:none}.composer-wrap{padding:9px}.composer{grid-template-columns:38px 1fr 45px}.composer button:nth-of-type(2){display:none}}
</style><meta name="csrf-token" content="{{ csrf_token() }}"><meta name="weai-endpoint" content="{{ route('weai.chat', [], false) }}"><link rel="stylesheet" href="{{ asset('css/weai.css') }}"></head><body><header class="top"><button class="mobile" id="menu">☰</button><a class="brand" href="{{ route('home') }}"><span class="mark"></span><span class="word">We<span>talk</span></span></a><label class="search"><input id="search" placeholder="Search anything…"><kbd>Ctrl K</kbd></label><button class="bell">♧<i>3</i></button><div class="user"><span class="avatar">MI</span><span><b>Musa Ibrahim</b><small>Admin</small></span>⌄</div></header><div class="shell"><aside class="global" id="global"><button class="create">＋ &nbsp; Create Community</button><div class="label">Main</div><a class="nav-btn active" href="#"><span class="ico">⌂</span>Home</a><button class="nav-btn"><span class="ico">♧</span>Communities</button><button class="nav-btn"><span class="ico">♘</span>Channels</button><button class="nav-btn"><span class="ico">◯</span>Direct Messages</button><button class="nav-btn"><span class="ico">♧</span>Notifications<span class="count">3</span></button><button class="nav-btn"><span class="ico">□</span>Events</button><button class="nav-btn"><span class="ico">▱</span>Files</button><button class="nav-btn"><span class="ico">▤</span>Saved Messages</button><button class="nav-btn"><span class="ico">⚙</span>Settings</button><div class="label">Communities</div><button class="item active"><span class="community-dot">GU</span>Greenfield University</button><button class="item"><span class="community-dot green">BT</span>Business Team</button><button class="item"><span class="community-dot purple">CG</span>Church Group</button><button class="item"><span class="community-dot orange">NG</span>Neighborhood</button><div class="me"><span class="avatar">MI</span><span><b>Musa Ibrahim</b><small>Online</small></span></div></aside><aside class="channels"><div class="workspace"><span class="community-dot">GU</span><b>Greenfield University</b><span style="margin-left:auto">⌄</span></div><div class="channel-list"><div class="row-label">Channels <button>＋</button></div><button class="item active" data-channel="general"># &nbsp; general</button><button class="item" data-channel="announcements"># &nbsp; announcements 📣</button><button class="item" data-channel="events"># &nbsp; events</button><button class="item" data-channel="resources"># &nbsp; resources</button><button class="item" data-channel="assignments"># &nbsp; assignments</button><button class="item" data-channel="off-topic"># &nbsp; off-topic</button><div class="voice-sep"><div class="row-label">Voice Channels <button>＋</button></div><button class="item">♬ &nbsp; General Voice</button><button class="item">♬ &nbsp; Study Room</button></div></div></aside><main class="chat"><header class="chat-head"><span style="font-size:23px">#</span><div><h1 id="title">general</h1><p>General discussion for everyone.</p></div><div class="chat-tools"><button>♧</button><button>♙</button><button>⌘</button><button>⋮</button></div></header><section class="messages" id="messages"><article class="message"><span class="avatar">MI</span><div><div class="meta"><b>Musa Ibrahim</b><time>10:30 AM</time></div><div class="text">Good morning everyone! 👋<br>Hope you all have a great day.</div><div class="reactions"><button class="react">👍 12</button><button class="react">❤️ 4</button></div></div></article><article class="message"><span class="avatar" style="background:linear-gradient(145deg,#ef2028,#ff7078)">AB</span><div><div class="meta"><b style="color:#ef2028">Aisha Bello</b><time>10:32 AM</time></div><div class="text">Good morning Musa! ☀️<br>Yes, have a productive day everyone.</div></div></article><article class="message"><span class="avatar" style="background:linear-gradient(145deg,#0b7d57,#22ba82)">IM</span><div><div class="meta"><b>Ibrahim Musa</b><time>10:35 AM</time></div><div class="text">Don’t forget about the community<br>meeting tomorrow at 6 PM.</div><div class="reactions"><button class="react">✅ 8</button></div></div></article><article class="message"><span class="avatar" style="background:linear-gradient(145deg,#8743dc,#b975ed)">AD</span><div><div class="meta"><b style="color:#8644de">Admin</b><time>10:40 AM</time></div><div class="announce"><b>📣 Announcement</b>Community Meeting tomorrow<br>at 6 PM. Please be there!</div></div></article><div class="new"><span>New Messages</span></div><article class="message"><span class="avatar">MI</span><div><div class="meta"><b>Musa Ibrahim</b><time>10:45 AM</time></div><div class="text">Thanks everyone! See you tomorrow.</div></div></article></section><div class="composer-wrap"><form class="composer" id="form"><button type="button">🔗</button><input id="input" placeholder="Type a message…"><button type="button">☺</button><button class="send">➤</button></form></div></main><aside class="right"><section class="card"><h2>Online Members (32)</h2><div id="members"></div><p class="more">+27 more</p></section><section class="card"><h2>Community Info</h2><div class="stat"><span>◉ Created</span><b>Jan 15, 2024</b></div><div class="stat"><span>♙ Members</span><b>1,248</b></div><div class="stat"><span>▣ Channels</span><b>12</b></div><div class="stat"><span>▱ Files</span><b>342</b></div><button class="settings">⚙ &nbsp; View Community Settings</button></section></aside></div><div class="overlay" id="overlay"></div><script>
const $=s=>document.querySelector(s),people=[['MI','Musa Ibrahim','Admin'],['AB','Aisha Bello','Mod'],['IM','Ibrahim Musa',''],['FA','Fatima Ali',''],['UK','Usman K.','']];$('#members').innerHTML=people.map(p=>`<div class="member"><span class="avatar">${p[0]}</span><span><b>${p[1]}</b><small>Online</small></span>${p[2]?`<span class="role">${p[2]}</span>`:''}</div>`).join('');document.querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>{$('#title').textContent=b.dataset.channel;document.querySelectorAll('[data-channel]').forEach(x=>x.classList.toggle('active',x===b))});$('#form').onsubmit=e=>{e.preventDefault();const v=$('#input').value.trim();if(!v)return;$('#messages').insertAdjacentHTML('beforeend',`<article class="message"><span class="avatar">YO</span><div><div class="meta"><b>You</b><time>Now</time></div><div class="text">${v.replace(/[<>]/g,'')}</div></div></article>`);$('#input').value='';$('#messages').scrollTop=$('#messages').scrollHeight};$('#search').oninput=e=>{document.querySelectorAll('.message').forEach(m=>m.style.display=m.textContent.toLowerCase().includes(e.target.value.toLowerCase())?'grid':'none')};$('#menu').onclick=()=>{$('#global').classList.toggle('open');$('#overlay').classList.toggle('open')};$('#overlay').onclick=()=>{$('#global').classList.remove('open');$('#overlay').classList.remove('open')};document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search').focus()}});
</script><style>.translate{display:block;margin-top:6px;border:0;background:transparent;color:var(--b);font-size:9px;padding:0}.modal{display:none;position:fixed;inset:0;z-index:30;align-items:center;justify-content:center;padding:18px}.modal.open{display:flex}.panel{width:min(390px,100%);background:#fff;border-radius:20px;padding:22px;box-shadow:0 30px 80px #06142d55;text-align:center}.panel h2{margin:0 0 8px}.panel p{color:var(--m);font-size:12px}.panel img{width:190px;height:190px;margin:14px auto;display:block}.panel button{border:0;border-radius:10px;padding:11px 15px}.panel .primary{display:block;width:100%;margin-top:14px;background:var(--b);color:#fff;font-weight:800}.panel .close{float:right;background:#eef3f9}.personal-list{border-top:1px solid var(--l);margin:18px -13px 0;padding:15px 13px 0}</style><div class="modal" id="qrModal"><div class="panel"><button class="close" id="qrClose">✕</button><h2>Invite to WeTalk</h2><p>Scan this QR code or share the link. No phone number or SIM required.</p><img alt="WeTalk invite QR" src="https://api.qrserver.com/v1/create-qr-code/?size=300x300&amp;data=https%3A%2F%2Fwww.wetalk.co%2Fjoin"><b>www.wetalk.co/join</b><button class="primary" id="copyLink">Copy invite link</button></div></div><script>
const directButton=[...document.querySelectorAll('.nav-btn')].find(x=>x.textContent.includes('Direct Messages'));const qrButton=document.createElement('button');qrButton.className='nav-btn';qrButton.innerHTML='<span class="ico">▦</span>Invite with QR';directButton.after(qrButton);const personal=document.createElement('div');personal.className='personal-list';personal.innerHTML='<div class="row-label">Personal Chats <button>＋</button></div><button class="item dm" data-user="Aisha Bello">● &nbsp; Aisha Bello</button><button class="item dm" data-user="Ibrahim Musa">● &nbsp; Ibrahim Musa</button><button class="item dm" data-user="Fatima Ali">● &nbsp; Fatima Ali</button>';document.querySelector('.channel-list').append(personal);const originalMessages=$('#messages').innerHTML;document.querySelectorAll('.text').forEach((el,i)=>{const b=document.createElement('button');b.className='translate';b.textContent='Translate message';b.onclick=()=>{if(b.dataset.done){el.innerHTML=b.dataset.original;b.textContent='Translate message';delete b.dataset.done}else{b.dataset.original=el.innerHTML;el.textContent=['Bonjour ! Ce message a été traduit automatiquement.','¡Hola! Este mensaje fue traducido automáticamente.','Sannu! An fassara wannan saƙon ta atomatik.'][i%3];b.textContent='Show original';b.dataset.done='1'}};el.after(b)});document.querySelectorAll('.dm').forEach(b=>b.onclick=()=>{$('#title').textContent=b.dataset.user;$('#messages').innerHTML=`<article class="message"><span class="avatar">${b.dataset.user.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><div><div class="meta"><b>${b.dataset.user}</b><time>Now</time></div><div class="text">This is a private personal chat. Say hello!</div></div></article>`});directButton.onclick=()=>document.querySelector('.dm').click();const openQR=()=>{$('#overlay').classList.add('open');$('#qrModal').classList.add('open')};qrButton.onclick=openQR;$('#qrClose').onclick=()=>{$('#overlay').classList.remove('open');$('#qrModal').classList.remove('open')};$('#copyLink').onclick=()=>{navigator.clipboard?.writeText('https://www.wetalk.co/join');$('#copyLink').textContent='Invite link copied ✓'};const setup=JSON.parse(localStorage.getItem('wetalk-onboarding')||'null');if(setup?.name){document.querySelectorAll('.user b,.me b').forEach(x=>x.textContent=setup.name)}
</script><script src="{{ asset('js/weai.js') }}" defer></script></body></html>
